-- GenDB engine variant Q13-conjunct_permutation: template q13.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  c_count,
  COUNT(*) AS custdist
FROM (
  SELECT
    c_custkey,
    COUNT(o_orderkey) AS c_count
  FROM customer
  LEFT OUTER JOIN orders
    ON NOT o_comment LIKE $1 AND c_custkey = o_custkey
  GROUP BY
    c_custkey
) AS c_orders
GROUP BY
  c_count
ORDER BY
  custdist DESC,
  c_count DESC
